using System.Diagnostics;
using System.Text.Json;
using System.Text.Json.Nodes;
namespace RisingLands;
public static class MissionSevenTests {
 static readonly List<string> checks=new();static readonly List<object> runs=new();
 static void Check(bool ok,string label){if(!ok)throw new InvalidDataException("FAIL M7: "+label);checks.Add(label);Console.WriteLine("PASS M7: "+label);}
 static Simulation Load(string root,int branch=2){var w=LegacyAssets.Map(PackageLayout.Asset(root,"CD/WORLD/MONDE07.ETA"));new VisualCatalog().Apply(w);return new(w,new(){StartingLevels=Simulation.UnlockData.Missions.First(m=>m.Mission==7).Levels.ToArray(),SelectedBranch=branch});}
 static void Advance(Simulation s,int count){for(int i=0;i<count;i++)s.Step();}
 static void Farm(Simulation s){var f=s.World.Units.First(a=>a.Owner==0&&a.Type==5);Check(s.SetFoodDestination(f,2,s.World.Buildings.First(b=>b.Type==3).Slot)&&s.GatherNearest(f),"ordinary farmer receives collection/deposit loop");}
 static int Lab(Simulation s,int workers){int lab=ResearchTests.Build(s,7,false);Check(s.World.Resources[4]==28&&s.World.Buildings.Any(b=>b.Slot==lab&&b.Type==7),"laboratory built with real native opening resources");var settlers=s.World.Units.Where(a=>a.Owner==0&&a.Type==9&&VisualCatalog.Visible(a)).Take(workers).ToList();while(settlers.Count<workers){var released=s.ReleaseResident(s.World.Buildings.First(b=>b.Type==2).Slot);if(released==null)throw new InvalidDataException("Missing available researcher; units="+JsonSerializer.Serialize(s.World.Units.Where(a=>a.Type==9)));settlers.Add(released);}foreach(var a in settlers)Check(s.EnterBuilding(a,lab),"free colonist enters laboratory by ordinary order");for(int i=0;i<3000&&s.Scientists()<workers;i++)s.Step();Check(s.Scientists()==workers,"laboratory occupied by requested scientists");return lab;}
 static void Roundtrip(string root,Simulation s,string label){var copy=Load(root,s.Research.InitialBranch);copy.Restore(s.Serialize());Check(copy.Serialize()==s.Serialize(),label);}
 static void Reject(Simulation s,JsonNode bad,string label){string before=s.Serialize();bool rejected=false;try{s.Restore(bad.ToJsonString());}catch(InvalidDataException){rejected=true;}Check(rejected&&s.Serialize()==before,label);}
 public static void Benchmark(string root,string output){var s=Load(root);var beast=s.World.Units.Single(a=>a.Type==21);bool route=s.Order(beast,87,58,true);Console.WriteLine("Initial creature path to player: "+route+", length="+beast.Route.Count);s.Restart();var times=new List<double>();for(int i=0;i<1800;i++){long t=Stopwatch.GetTimestamp();s.Step();times.Add(Stopwatch.GetElapsedTime(t).TotalMilliseconds);}beast=s.World.Units.Single(a=>a.Type==21);var result=new{MeanMs=times.Average(),P95Ms=times.Order().ElementAt((int)(times.Count*.95)),MaxMs=times.Max(),InitialPath=route,CreatureCell=beast.Y/1024*256+beast.X/1024,Route=beast.Route.Count,Siege=s.Opponent.Sieges.GetValueOrDefault(beast.Slot),Limit="Simulation CPU only; 1800 native opening ticks."};File.WriteAllText(output,JsonSerializer.Serialize(result,new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine(JsonSerializer.Serialize(result));}
 public static void Run(string root,string output){checks.Clear();runs.Clear();var s=Load(root);string initial=s.Serialize();
  Check(s.IsSeventhMission&&s.HasMissionEnding&&!s.MissionWon&&!s.MissionLost,"active mission-seven objective starts unfinished");
  Check(s.World.Width==192&&s.World.Height==192&&s.World.Units.Count==16&&s.World.Buildings.Count==4,"native dimensions, actors and four buildings preserved");
  Check(s.World.Resources[0]==35&&s.World.Resources[4]==40&&s.World.Resources[8]==10,"opening resources 35/40/10 preserved");
  Check(!s.OpponentEnabled&&s.World.Units.All(a=>a.Owner is 0 or 4),"no fabricated economic enemy clans");
  Check(s.World.Units.Single(a=>a.Type==21).Owner==4&&!s.NeedsFood(s.World.Units.Single(a=>a.Type==21)),"native Raptor becomes hostile fauna, not a player survivor");
  Check(!s.UnitInSight(s.World.Units.Single(a=>a.Type==21)),"fauna does not reveal its own fog to player");
  var objective=new ObjectiveReader();objective.Open("MONDE07.ETA",false);objective.Move(1);Check(objective.Lines.Any(l=>l.Contains("duas tecnologias")),"original mission objective available in Portuguese");
  Roundtrip(root,s,"opening save roundtrip");Advance(s,100);Check(!s.MissionWon&&s.MissionResearchCount==0,"waiting cannot win");s.Restart();Check(s.Serialize()==initial,"restart resets creatures, resources and research");
  var old=JsonNode.Parse(initial)!;old["Version"]=41;old.AsObject().Remove("Creatures");foreach(var a in old["Units"]!.AsArray())if(a!["Type"]!.GetValue<int>()==21)a["Owner"]=0;s.Restore(old.ToJsonString());Check(s.World.Units.Single(a=>a.Type==21).Owner==4,"legacy mission-seven save migrates native fauna ownership in memory");
  var bad=JsonNode.Parse(initial)!;bad["Tick"]=100;bad["MissionChecks"]=100;Reject(s,bad,"forged victory without two actual researches rejected atomically");
  foreach(int branch in Enumerable.Range(0,4))foreach(int staff in new[]{1,2}){
   s=Load(root,branch);Farm(s);int lab=Lab(s,staff);Check(s.MissionResearchCount==0&&!s.MissionWon,"laboratory alone is not victory, branch "+branch+" staff "+staff);
   int notices=0;s.ResearchCompleted+=t=>notices++;long start=s.Tick;var watch=Stopwatch.StartNew();var samples=new List<double>();bool savedOne=false;
   for(int i=0;i<33000&&!s.MissionWon&&!s.MissionLost;i++){
    long stamp=Stopwatch.GetTimestamp();s.Step();samples.Add(Stopwatch.GetElapsedTime(stamp).TotalMilliseconds);
    if(!savedOne&&s.MissionResearchCount==1){Check(!s.MissionWon,"first discovery cannot finish branch "+branch+" staff "+staff);Roundtrip(root,s,"one-discovery save branch "+branch+" staff "+staff);savedOne=true;}
   }
   Check(s.MissionWon&&!s.MissionLost&&s.MissionResearchCount==2&&notices==2,"natural mission completion with branch "+branch+" and "+staff+" scientists");
   Check(s.Tests.Technologies.Count==0&&!s.Tests.Victory&&!s.Research.ExtraPurchased,"route uses no debug grants or paid extra research");Roundtrip(root,s,"victory roundtrip branch "+branch+" staff "+staff);
   if(branch==3){Check(s.SpellUnlocked(0),"spiritual first discovery unlocks vision spell");Check(s.SpiritualDamageBonus(s.World.Units.First(a=>a.Type==4))==2,"spiritual second discovery adds native +2 Druid damage");}
   s.RequestNextMission();Check(s.ChooseNextResearch(branch),"next-branch selection after mission-seven victory");var w=LegacyAssets.Map(PackageLayout.Asset(root,"CD/WORLD/MONDE08.ETA"));new VisualCatalog().Apply(w);var next=new Simulation(w,s.ProgressForNextMission());Check(next.MissionNumber==8&&next.Campaign.CompletedMission==7&&next.Campaign.SelectedBranch==branch,"7 to 8 campaign transition preserves choice");
   var ordered=samples.Order().ToArray();runs.Add(new{Branch=branch,Scientists=staff,Start=start,End=s.Tick,Seconds=(s.Tick-start)/30.0,Research=s.MissionResearchCount,Arrivals=s.Creatures.Arrivals.Count,Survivors=s.World.Units.Count(a=>a.Owner==0&&a.Health>0),MeanMs=samples.Average(),P95Ms=ordered[(int)(ordered.Length*.95)],MaxMs=ordered[^1],RealSeconds=watch.Elapsed.TotalSeconds});
   File.WriteAllText(Path.Combine(Path.GetDirectoryName(output)!,"routes-progress.json"),JsonSerializer.Serialize(runs,new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine("SIMULATION M7: branch="+branch+" staff="+staff+" mean="+samples.Average()+" ms");
   if(branch==2&&staff==2)File.WriteAllText(Path.Combine(Path.GetDirectoryName(output)!,"natural-victory.snapshot.json"),s.Serialize());
  }
  s=Load(root);Farm(s);Advance(s,16200);Check(s.Creatures.Arrivals.Any(a=>a.Entry==3&&a.Tick==16200)&&s.Creatures.Arrivals.Sum(a=>a.Seeds.Count)==1,"first western timed arrival at 540*30 ticks");Roundtrip(root,s,"spawned actor save validates independently of born colonists");
  var copy=Load(root);copy.Restore(s.Serialize());Advance(s,9000);Advance(copy,9000);Check(s.Serialize()==copy.Serialize(),"creature navigation and second spawn deterministic after load");Check(s.Creatures.Arrivals.Any(a=>a.Entry==1&&a.Tick==25200),"eastern timed arrival at 840*30 ticks");
  var altered=JsonNode.Parse(s.Serialize())!;altered["Creatures"]!["Arrivals"]![0]!["Seeds"]![0]!["Owner"]=0;Reject(s,altered,"forged creature ownership rejected atomically");
  s=Load(root);var beast=s.World.Units.Single(a=>a.Type==21);var defender=s.World.Units.First(a=>a.Owner==0&&a.Type==8);beast.X=defender.X+3*1024;beast.Y=defender.Y;s.UpdateVisibility();Check(s.CanAttack(defender,beast)&&s.CanAttack(beast,defender),"player and Raptor support reciprocal combat");Check(s.Attack(defender,beast),"ordinary player attack targets native creature");Advance(s,35);Check(beast.Health<100||defender.Health<100,"native creature/player attack causes real damage");Roundtrip(root,s,"combat with neutral fauna saves projectiles and windups");var visual=new VisualCatalog();Check(Simulation.CreatureAttacks.Types.Single(v=>v.Type==21).Frames.Count>0&&visual.ProjectileCommands(24,0).Count>0,"native Raptor attack frames and projectile exist");
  s=Load(root);beast=s.World.Units.Single(a=>a.Type==21);var warehouse=s.World.Buildings.First(b=>b.Type==3);beast.X=((warehouse.Cell&255)-1)*1024;beast.Y=((warehouse.Cell>>8)+2)*1024;Check(s.AttackBuilding(beast,warehouse.Slot),"creature may assault structures");Advance(s,120);Check(s.BuildingHealth(warehouse)<s.BuildingMaxHealth(warehouse),"creature siege diminishes structure health");Roundtrip(root,s,"creature siege and building damage persist");
  s=Load(root);foreach(var a in s.World.Units.Where(a=>a.Owner==0)){a.Health=0;a.Route.Clear();}Check(s.MissionLost,"hostile Raptor is not counted as player survivor after defeat");long halted=s.Tick;s.Step();Check(s.Tick==halted,"defeat stops simulation");s.Restart();Check(!s.MissionLost,"restart recovers from defeat");
  File.WriteAllText(output,JsonSerializer.Serialize(new{Passed=true,Checks=checks.Count,Assertions=checks,Runs=runs,Limits="Headless simulations using actual ordinary gameplay commands. Combat/corruption/defeat edge cases use isolated fixtures. No manual UI campaign or real user save writes."},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine("PASS M7 total "+checks.Count);
 }
}
